# TEMP verify site for bug-6373 fix (worktree dist). Remove after verification.
server {
    listen 8099;
    server_name localhost;
    root D:/repository/苏州市房地产监测V3-wt-bug-6373/dist;
    index index.html;
    charset utf-8;
    client_max_body_size 100m;
    location ~* \.(js|css|png|jpg|jpeg|gif|ico|svg|woff|woff2|ttf|eot|map|json|xlsx)$ {
        expires 7d;
        add_header Cache-Control "public" always;
        access_log off;
        try_files $uri =404;
    }
    location = /index.html {
        expires -1;
        add_header Cache-Control "no-cache, no-store, must-revalidate";
        add_header Pragma "no-cache";
    }
    proxy_http_version 1.1;
    proxy_set_header Connection "";
    proxy_set_header Host $host;
    proxy_set_header X-Real-IP $remote_addr;
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    proxy_set_header X-Forwarded-Proto $scheme;
    proxy_connect_timeout 60s;
    proxy_send_timeout 120s;
    proxy_read_timeout 120s;
    location /api/v3.0/ {
        proxy_pass http://127.0.0.1:8080/v3.0/;
        proxy_set_header Host 127.0.0.1:8080;
    }
    location ^~ /zhi2/ {
        proxy_pass http://127.0.0.1:8080;
    }
    location ^~ /zhi2-dev/ {
        proxy_pass http://127.0.0.1:8080;
    }
    location ^~ /zhi2-test/ {
        proxy_pass http://127.0.0.1:8080;
    }
    location / {
        try_files $uri $uri/ /index.html;
    }
}
